parameters.jsCode:
const items = $input.all();
return items.map(item => {
  const payload = item.json.body || item.json;
  const action = payload.action || {};
  const data = action.data || {};
  const card = data.card || {};
  const listAfter = data.listAfter || {};
  const listBefore = data.listBefore || {};
  const member = action.memberCreator || {};

  const isBlocked = (listAfter.name || '').toLowerCase().includes('blocked') ||
                    (listAfter.name || '').toLowerCase().includes('stuck');

  return {
    json: {
      cardId: card.id || '',
      cardName: card.name || '',
      fromColumn: listBefore.name || '',
      toColumn: listAfter.name || '',
      boardName: data.board?.name || '',
      movedBy: member.fullName || member.username || '',
      actionType: action.type || '',
      isBlocked: isBlocked,
      cardUrl: card.shortUrl || `https://trello.com/c/${card.shortLink || ''}`,
      timestamp: action.date || new Date().toISOString()
    }
  };
});

